import {houseDescriptor,ROOM,furniturePose} from './housing-data.js?v=20261011-life82';
export function livingHome(position,rooms){if(!position)return null;for(const index of Object.keys(rooms||{})){const h=houseDescriptor(index);if(h&&Math.abs(position.x-h.x)<ROOM.x&&Math.abs(position.z-h.z)<ROOM.z&&position.y>=ROOM.floor-.3&&position.y<ROOM.floor+ROOM.height)return h;}return null;}
export function livingKind(def){const s=def?.design,f=def?.family;if(['bike','treadmill'].includes(s))return 'exercise';if(['canvas','easel'].includes(s))return 'paint';if(s==='sewing')return 'sewing';if(['washer','dryer'].includes(s))return 'laundry';if(['bath','bathtub','shower'].includes(s)||['bath','bathtub'].includes(f))return 'bath';if(['trash','recycle'].includes(s))return 'trash';if(s==='microwave')return 'microwave';if(s==='chess'||s==='board')return 'chess';if(s==='basketball')return 'basketball';if(s==='globe')return 'globe';if(s==='horse')return 'horse';if(['train','car','blocks','dollhouse'].includes(s))return 'toy';if(f==='tv'||f==='electronics'&&(s?.startsWith('tv-')||s==='crt'))return 'tv';if(f==='computer'||f==='electronics'&&['pc','laptop','tablet'].includes(s))return 'pc';return 'object';}
export function livingPose(index,item){const h=houseDescriptor(index),p=furniturePose(item);return {x:h.x+p.x*h.front,y:ROOM.floor+p.centerY,z:h.z+p.z*h.front,yaw:p.yaw+(h.front<0?Math.PI:0),w:p.w*.88,h:p.h*.88,d:p.d*.88};}
export function rhythm(run,now){const elapsed=Math.max(0,(now-run.startAt)/1000),period=Math.max(.85,2.6-elapsed*.012),phase=((now-run.beatAt)/1000/run.period)%1;return {period,phase:Math.max(0,phase),window:Math.max(.045,.14-elapsed*.0007)};}
export const chessStart=()=>({board:[...'rnbqkbnrpppppppp................................PPPPPPPPRNBQKBNR'],turn:'white',moves:0});
const white=p=>p&&p!=='.'&&p===p.toUpperCase();
function attacks(b,from,to){const p=b[from].toLowerCase(),dx=to%8-from%8,dy=Math.floor(to/8)-Math.floor(from/8),ax=Math.abs(dx),ay=Math.abs(dy);if(p==='p')return ax===1&&dy===(white(b[from])?-1:1);if(p==='n')return ax*ay===2;if(p==='k')return Math.max(ax,ay)===1;if(!(['q','r'].includes(p)&&(dx===0||dy===0)||['q','b'].includes(p)&&ax===ay))return false;const step=Math.sign(dx)+Math.sign(dy)*8;for(let i=from+step;i!==to;i+=step)if(b[i]!=='.')return false;return true;}
export function chessMove(state,from,to){if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>63||to>63||from===to)return null;const b=state.board,p=b[from];if(p==='.'||white(p)!==(state.turn==='white')||b[to]!=='.'&&white(b[to])===white(p)||b[to].toLowerCase()==='k')return null;let legal=attacks(b,from,to);if(p.toLowerCase()==='p'){const dir=white(p)?-8:8;legal=b[to]!=='.'?attacks(b,from,to):to===from+dir||Math.floor(from/8)===(white(p)?6:1)&&to===from+dir*2&&b[from+dir]==='.';}if(!legal)return null;const next=[...b];next[to]=p;next[from]='.';if(p.toLowerCase()==='p'&&[0,7].includes(Math.floor(to/8)))next[to]=white(p)?'Q':'q';const king=next.indexOf(white(p)?'K':'k');if(next.some((other,i)=>other!=='.'&&white(other)!==white(p)&&attacks(next,i,king)))return null;return {board:next,turn:state.turn==='white'?'black':'white',moves:state.moves+1};}
